<?php
namespace Delnavazan\Platform\Admin\Controller;
final class AdminDashboardController {
 public static function register():void{add_action('wp_dashboard_setup',[self::class,'widgets']);}
 public static function widgets():void{if(!current_user_can('dzn_view_diagnostics'))return;wp_add_dashboard_widget('dzn_academy_snapshot','Delnavazan · Academy snapshot',[self::class,'snapshot']);wp_add_dashboard_widget('dzn_attention_snapshot','Delnavazan · Needs attention',[self::class,'attention']);wp_add_dashboard_widget('dzn_readiness_snapshot','Delnavazan · Launch readiness',[self::class,'readiness']);}
 public static function snapshot():void{global $wpdb;$p=$wpdb->prefix.'dzn_';$facts=['Students'=>"SELECT COUNT(*) FROM {$p}students WHERE archived_at IS NULL",'Teachers'=>"SELECT COUNT(*) FROM {$p}teachers WHERE archived_at IS NULL",'Open booking requests'=>"SELECT COUNT(*) FROM {$p}booking_requests WHERE privacy_erased_at IS NULL AND resolution_state='unresolved'",'Active enrolments'=>"SELECT COUNT(*) FROM {$p}enrolments WHERE archived_at IS NULL AND lifecycle_state='active'"];echo '<table class="widefat striped"><tbody>';foreach($facts as$l=>$q)echo '<tr><th>'.esc_html($l).'</th><td><strong>'.(int)$wpdb->get_var($q).'</strong></td></tr>';echo '</tbody></table><p><a class="button button-primary" href="'.esc_url(admin_url('admin.php?page=dzn-academy-dashboard')).'">Open Academy</a></p>';}
 public static function attention():void{global $wpdb;$p=$wpdb->prefix.'dzn_';$facts=[['Operational exceptions',"SELECT COUNT(*) FROM {$p}operational_exceptions WHERE status='open'",'dzn-exception'],['Teacher profiles in setup',"SELECT COUNT(*) FROM {$p}teacher_onboarding_states WHERE state IN ('linked_pending','in_progress','returned','rejected')",'dzn-teachers-menu&view=onboarding'],['Requests needing coordination',"SELECT COUNT(*) FROM {$p}booking_requests br LEFT JOIN {$p}coordination_cases cc ON cc.booking_request_id=br.id WHERE br.privacy_erased_at IS NULL AND br.resolution_state='unresolved' AND cc.id IS NULL",'dzn-academy-dashboard']];if(current_user_can('dzn_manage_canonical_attendance_review'))$facts[]=['Absence reports needing administrator review',"SELECT COUNT(DISTINCT c.id) FROM {$p}canonical_attendance_cases c INNER JOIN {$p}canonical_attendance_evidence e ON e.case_id=c.id LEFT JOIN {$p}canonical_lesson_schedule_versions v ON v.id=c.schedule_version_id AND v.lesson_id=c.lesson_id WHERE c.state IN ('open','ready_for_review','settlement_pending') AND e.source_kind='student' AND (v.id IS NULL OR (v.applicable_slot=1 AND v.superseded_at IS NULL)) AND NOT EXISTS (SELECT 1 FROM {$p}lesson_reschedule_proposals rp WHERE rp.lesson_id=c.lesson_id AND rp.created_at>=c.created_at AND (rp.state IN ('committing','accepted') OR (rp.state='pending' AND (rp.expires_at IS NULL OR rp.expires_at>UTC_TIMESTAMP()))))",'dzn-attendance-review'];if(current_user_can('dzn_manage_lessons'))$facts[]=['Class time changes awaiting student response',"SELECT COUNT(*) FROM {$p}lesson_reschedule_proposals WHERE state='pending'",'dzn-lesson'];echo '<table class="widefat striped"><tbody>';foreach($facts as[$l,$q,$page]){echo '<tr><th><a href="'.esc_url(admin_url('admin.php?page='.$page)).'">'.esc_html($l).'</a></th><td><strong>'.(int)$wpdb->get_var($q).'</strong></td></tr>';}echo '</tbody></table><p class="description">Only unresolved work is shown here. Open the linked authority screen to investigate or act.</p>';}
 public static function readiness():void{global $wpdb;$p=$wpdb->prefix.'dzn_';$readyTeachers=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$p}teacher_onboarding_states o INNER JOIN {$p}teachers t ON t.id=o.teacher_id WHERE o.state='active' AND o.readiness_state='ready' AND t.status='active' AND t.archived_at IS NULL");$products=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$p}commercial_products WHERE status='active' AND archived_at IS NULL");$prices=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$p}commercial_prices WHERE status='active' AND archived_at IS NULL");$statements=(int)$wpdb->get_var("SELECT COUNT(*) FROM {$p}finance_statements WHERE state IN ('draft','issued')");$rows=[['Ready teachers',$readyTeachers,'dzn-teachers-menu'],['Active commercial products',$products,'dzn-finance&tab=settings'],['Active regional prices',$prices,'dzn-finance&tab=settings'],['Live teacher statements',$statements,'dzn-finance&tab=statements']];echo '<table class="widefat striped"><tbody>';foreach($rows as[$l,$n,$page])echo '<tr><th><a href="'.esc_url(admin_url('admin.php?page='.$page)).'">'.esc_html($l).'</a></th><td><strong>'.(int)$n.'</strong></td></tr>';echo '</tbody></table><p class="description">Readiness indicators only; zero is not automatically an error. Configuration and real operational data determine what is required.</p>';}
}
